    .contact {
      text-align: center;
    }

    .contact a {
      display: inline-block;
      margin-top: 0.5rem;
      text-decoration: none;
      background: var(--primary);
      color: white;
      border-radius: 999px;
      padding: 0.85rem 1.5rem;
      font-weight: 700;
      transition: transform 0.15s ease, box-shadow 0.15s ease;
    }

    .contact a:hover {
      transform: translateY(-3px);
      box-shadow: 0 6px 14px rgba(0,0,0,0.12);
    }

    footer {
      text-align: center;
      padding: 2rem 1rem;
      color: #8a7f75;
      font-size: 0.95rem;
    }

    /* Floating particles */
    .particle {
      position: absolute;
      pointer-events: none;
      font-size: 1.5rem;
      animation: floatUp 1.2s ease-out forwards;
      z-index: 10;
    }

    @keyframes floatUp {
      0% { opacity: 1; transform: translateY(0) scale(1); }
      100% { opacity: 0; transform: translateY(-120px) scale(1.4); }
    }

    .treat-fly {
      position: absolute;
      font-size: 2rem;
      pointer-events: none;
      animation: flyToMouth 0.8s ease-in forwards;
      z-index: 10;
    }

    @keyframes flyToMouth {
      0% { opacity: 1; transform: translate(0, 0) scale(1); }
      100% { opacity: 0; transform: translate(var(--tx), var(--ty)) scale(0.5); }
    }

    .toast {
      position: fixed;
      bottom: 1.5rem;
      left: 50%;
      transform: translateX(-50%);
      background: #3d3d3d;
      color: white;
      padding: 0.75rem 1.25rem;
      border-radius: 999px;
      font-size: 0.95rem;
      opacity: 0;
      transition: opacity 0.3s ease;
      pointer-events: none;
      z-index: 100;
    }

    .toast.show { opacity: 1; }

    @media (max-width: 600px) {
      section { padding: 1.5rem; }
      .hero { gap: 1.5rem; }
    }
  </style>
</head>
<body>
  <header>
