          <circle cx="120" cy="86" r="2.5" fill="#fff" />
          <ellipse cx="100" cy="106" rx="10" ry="8" fill="#8b5a3c" />
          <path d="M94 114 Q 100 122 106 114" stroke="#8b5a3c" stroke-width="3" fill="none" stroke-linecap="round" />
          <path d="M96 112 Q 100 116 104 112" fill="#ff9eb5" opacity="0.6" />
          <ellipse cx="76" cy="112" rx="8" ry="5" fill="rgba(255,0,0,0.18)" />
