          <path d="M70 158 L76 176 L88 176 L82 158" fill="#e6bc86" stroke="#a67c52" stroke-width="3" stroke-linejoin="round" />
          <path d="M118 158 L124 176 L112 176 L106 158" fill="#e6bc86" stroke="#a67c52" stroke-width="3" stroke-linejoin="round" />
