  <footer>
    <p>Made with love for Pobrecita.</p>
  </footer>

  <div class="toast" id="toast"></div>

  <script>
    const tail = document.getElementById('tail');
    const dogContainer = document.getElementById('dogContainer');
    const petBtn = document.getElementById('petBtn');
    const treatBtn = document.getElementById('treatBtn');
    const shareBtn = document.getElementById('shareBtn');
    const treatCountSpan = document.getElementById('treatCount');
    const toast = document.getElementById('toast');

    let treats = 0;
    let wagTimer = null;

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      setTimeout(() => toast.classList.remove('show'), 2200);
    }

    function spawnParticle(emoji, x, y) {
      const p = document.createElement('span');
      p.className = 'particle';
      p.textContent = emoji;
      p.style.left = x + 'px';
      p.style.top = y + 'px';
      dogContainer.appendChild(p);
      setTimeout(() => p.remove(), 1200);
    }

    petBtn.addEventListener('click', () => {
      tail.classList.add('fast-wag');
      clearTimeout(wagTimer);
      wagTimer = setTimeout(() => tail.classList.remove('fast-wag'), 1500);

      const rect = dogContainer.getBoundingClientRect();
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;
      for (let i = 0; i < 6; i++) {
        const x = centerX + (Math.random() - 0.5) * 120;
        const y = centerY + (Math.random() - 0.5) * 80;
        spawnParticle('❤️', x, y);
      }
      showToast('Pobrecita wags her tail happily!');
    });

    treatBtn.addEventListener('click', (e) => {
      treats++;
      treatCountSpan.textContent = treats;

      const rect = dogContainer.getBoundingClientRect();
      const treat = document.createElement('span');
      treat.className = 'treat-fly';
      treat.textContent = '🦴';
      const startX = rect.width * 0.75;
      const startY = rect.height * 0.25;
      treat.style.left = startX + 'px';
      treat.style.top = startY + 'px';
      const endX = rect.width * 0.5 - startX;
      const endY = rect.height * 0.55 - startY;
      treat.style.setProperty('--tx', endX + 'px');
      treat.style.setProperty('--ty', endY + 'px');
      dogContainer.appendChild(treat);
      setTimeout(() => treat.remove(), 800);

      showToast('Crunch crunch! Pobrecita loves it.');
    });

    shareBtn.addEventListener('click', () => {
      const message = 'Meet Pobrecita, the sweetest little dog with the biggest heart! Visit her page to say hello.';
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(message).then(() => showToast('Copied to clipboard!'));
      } else {
        showToast(message);
      }
    });
  </script>
</body>
